/** 📈️diagram2d wire twin, mirrors `./🦀️.rs` (generated by `wp02-gen-twins.py`). */
import type { EntityRef, FieldBinding, Hatch, LocalizedCopy, QuantityKind, SectionShape, Tone, Triangle, Vec2, Vec3 } from "../🟦️.ts";

export interface Interval {
  min: number;
  max: number;
}

export interface Axis {
  label: LocalizedCopy;
  quantity: QuantityKind;
  unit: string;
  scale: AxisScale;
  domain: Interval | null;
  ticks: TickRule;
}

export interface Stroke {
  widthPx: number;
  dash: Dash;
  tone: Tone;
}

export interface Fill {
  tone: Tone;
  opacity: number;
}

export interface ScatterPoint {
  at: Vec2;
  tone: Tone;
  label: LocalizedCopy | null;
}

export interface Line2 {
  origin: Vec2;
  direction: Vec2;
}

export interface SectionProfile {
  points: Vec2[];
  unit: string;
}

export interface DiagramMesh {
  vertices: Vec3[];
  triangles: Triangle[];
}

export interface DiagramNote {
  id: string;
  at: Vec2;
  text: LocalizedCopy;
  tone: Tone;
}

export interface Marker {
  id: string;
  at: Vec2;
  shape: MarkerShape;
  tone: Tone;
  label: LocalizedCopy;
  utilisation: number | null;
  boundCheck: string | null;
  binding: FieldBinding | null;
}

export interface DataColumn {
  header: LocalizedCopy;
  unit: string;
  values: number[];
}

export interface DataTable {
  columns: DataColumn[];
}

export interface Diagram2d {
  id: string;
  title: LocalizedCopy;
  description: LocalizedCopy;
  axes: Axis[];
  series: Series[];
  markers: Marker[];
  annotations: DiagramNote[];
  focus: EntityRef | null;
  legend: boolean;
  tableTwin: DataTable;
}

export type AxisScale = "linear" | "log10" | "sqrt";

export type AxisRef = "x" | "y";

export type Dash = "solid" | "dashed" | "dotted";

export type MarkerShape = "circle" | "square" | "diamond" | "triangle" | "cross";

export type TickRule =
  | { kind: "auto" }
  | { kind: "step"; data: { step: number } }
  | { kind: "explicit"; data: { values: number[] } };

export type Series =
  | { kind: "polyline"; data: { id: string; label: LocalizedCopy; points: Vec2[]; style: Stroke } }
  | { kind: "polygon"; data: { id: string; label: LocalizedCopy; ring: Vec2[]; fill: Fill; hatch: Hatch | null } }
  | { kind: "band"; data: { id: string; label: LocalizedCopy; lower: Vec2[]; upper: Vec2[]; fill: Fill } }
  | { kind: "scatter"; data: { id: string; label: LocalizedCopy; points: ScatterPoint[] } }
  | { kind: "limit"; data: { id: string; label: LocalizedCopy; axis: AxisRef; value: number; style: Stroke } }
  | { kind: "section"; data: { id: string; label: LocalizedCopy; shape: SectionShape; strain: SectionProfile | null; stress: SectionProfile | null; neutralAxis: Line2 | null } }
  | { kind: "ray"; data: { id: string; label: LocalizedCopy; origin: Vec2; through: Vec2; toBoundary: boolean; style: Stroke } }
  | { kind: "surface3"; data: { id: string; label: LocalizedCopy; mesh: DiagramMesh } };
